CREATE TABLE IF NOT EXISTS users (
  id text PRIMARY KEY,
  email text UNIQUE NOT NULL,
  username text UNIQUE NOT NULL,
  password_hash text NOT NULL,
  full_name text,
  avatar_url text,
  role text NOT NULL DEFAULT 'user' CHECK (role IN ('owner', 'admin', 'user', 'guest')),
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive', 'suspended')),
  email_verified bigint DEFAULT 0,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  last_login_at timestamptz
);

CREATE TABLE IF NOT EXISTS teams (
  id text PRIMARY KEY,
  name text NOT NULL,
  description text,
  owner_id text NOT NULL,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  FOREIGN KEY (owner_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS team_members (
  id text PRIMARY KEY,
  team_id text NOT NULL,
  user_id text NOT NULL,
  role text NOT NULL CHECK (role IN ('owner', 'admin', 'user', 'guest')),
  invited_by text,
  joined_at timestamptz DEFAULT now(),
  FOREIGN KEY (team_id) REFERENCES teams (id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  FOREIGN KEY (invited_by) REFERENCES users (id),
  UNIQUE (team_id, user_id)
);

CREATE TABLE IF NOT EXISTS team_invitations (
  id text PRIMARY KEY,
  team_id text NOT NULL,
  email text NOT NULL,
  role text NOT NULL CHECK (role IN ('admin', 'user', 'guest')),
  invited_by text NOT NULL,
  token text UNIQUE NOT NULL,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'accepted', 'rejected', 'expired')),
  expires_at timestamptz NOT NULL,
  created_at timestamptz DEFAULT now(),
  FOREIGN KEY (team_id) REFERENCES teams (id) ON DELETE CASCADE,
  FOREIGN KEY (invited_by) REFERENCES users (id)
);

CREATE TABLE IF NOT EXISTS chat_sessions (
  id text PRIMARY KEY,
  user_id text NOT NULL,
  title text,
  model text NOT NULL,
  system_prompt text,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS chat_messages (
  id text PRIMARY KEY,
  session_id text NOT NULL,
  role text NOT NULL CHECK (role IN ('user', 'assistant', 'system')),
  content text NOT NULL,
  created_at timestamptz DEFAULT now(),
  FOREIGN KEY (session_id) REFERENCES chat_sessions (id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS skills (
  id text PRIMARY KEY,
  name text UNIQUE NOT NULL,
  version text NOT NULL DEFAULT '1.0.0',
  description text,
  enabled bigint DEFAULT 1,
  source text NOT NULL CHECK (source IN ('bundled', 'managed', 'workspace', 'marketplace')),
  file_path text NOT NULL,
  settings_schema text,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS skill_settings (
  id text PRIMARY KEY,
  skill_id text NOT NULL,
  user_id text NOT NULL,
  settings text NOT NULL,
  updated_at timestamptz DEFAULT now(),
  FOREIGN KEY (skill_id) REFERENCES skills (id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  UNIQUE (skill_id, user_id)
);

CREATE TABLE IF NOT EXISTS skill_secrets (
  id text PRIMARY KEY,
  skill_id text NOT NULL,
  user_id text NOT NULL,
  key text NOT NULL,
  encrypted_value text NOT NULL,
  iv text NOT NULL,
  auth_tag text NOT NULL,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  FOREIGN KEY (skill_id) REFERENCES skills (id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  UNIQUE (skill_id, user_id, key)
);

CREATE TABLE IF NOT EXISTS extensions (
  id text PRIMARY KEY,
  name text UNIQUE NOT NULL,
  version text NOT NULL DEFAULT '1.0.0',
  description text,
  type text NOT NULL CHECK (type IN ('channel', 'integration', 'ui', 'other')),
  enabled bigint DEFAULT 1,
  file_path text NOT NULL,
  config text,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS workflows (
  id text PRIMARY KEY,
  user_id text NOT NULL,
  name text NOT NULL,
  description text,
  enabled bigint DEFAULT 1,
  nodes text NOT NULL,
  edges text NOT NULL,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS workflow_executions (
  id text PRIMARY KEY,
  workflow_id text NOT NULL,
  status text NOT NULL CHECK (status IN ('running', 'completed', 'failed', 'cancelled')),
  started_at timestamptz DEFAULT now(),
  completed_at timestamptz,
  error text,
  logs text,
  FOREIGN KEY (workflow_id) REFERENCES workflows (id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS credentials (
  id text PRIMARY KEY,
  name text NOT NULL,
  type text NOT NULL,
  encrypted_value text NOT NULL,
  iv text NOT NULL,
  auth_tag text NOT NULL,
  description text,
  skill_id text,
  user_id text,
  refresh_token text,
  expires_at text,
  scopes text,
  created_at text NOT NULL,
  updated_at text NOT NULL,
  last_used text
);

CREATE TABLE IF NOT EXISTS scheduled_jobs (
  id text PRIMARY KEY,
  user_id text NOT NULL,
  name text NOT NULL,
  description text,
  cron_expression text NOT NULL,
  enabled bigint DEFAULT 1,
  workflow_id text,
  action text NOT NULL,
  last_run_at timestamptz,
  next_run_at timestamptz,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  FOREIGN KEY (workflow_id) REFERENCES workflows (id) ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS job_executions (
  id text PRIMARY KEY,
  job_id text NOT NULL,
  status text NOT NULL CHECK (status IN ('success', 'failed', 'cancelled')),
  started_at timestamptz DEFAULT now(),
  completed_at timestamptz,
  error text,
  logs text,
  FOREIGN KEY (job_id) REFERENCES scheduled_jobs (id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS memory_entries (
  id text PRIMARY KEY,
  user_id text NOT NULL,
  type text NOT NULL CHECK (type IN ('conversation', 'fact', 'preference', 'task', 'other')),
  key text NOT NULL,
  value text NOT NULL,
  importance double precision DEFAULT 0.5,
  embeddings bytea,
  metadata text,
  accessed_count bigint DEFAULT 0,
  last_accessed_at timestamptz,
  created_at timestamptz DEFAULT now(),
  expires_at timestamptz,
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS gateway_sessions (
  id text PRIMARY KEY,
